def compute(vars):
    compensation_cost = vars["v1"]
    income_tax_benefit = vars["v2"]
    after_tax_cost = compensation_cost + income_tax_benefit

    return {
        "value": after_tax_cost,
        "trace": {
            "compensation_cost": compensation_cost,
            "income_tax_benefit": income_tax_benefit,
            "after_tax_share_based_compensation_cost": after_tax_cost,
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": None
            }
        }
    }
